 for phase in ['baseline','after']:issues.append(dict(id=id,phase=phase,category=category,severity=severity,affected_urls=urls,affected_count=count,evidence=evidence,expected_benefit='Accurate discovery and usable guidance' if category!='performance' else 'Reduce forced layout during catalog initialization',confidence='High',difficulty='Low',recommended_action=action,owner='Kujo site maintainers',status='open' if phase=='baseline' else 'fixed'))
