  weight=lambda typ:sum(x.get('transferSize',0) for x in network if x.get('resourceType') in typ)
  perf.append(dict(phase=phase,url=j.get('finalDisplayedUrl',j.get('finalUrl')),template=f.stem.split('-')[-1],run_date=j.get('fetchTime'),environment='Lighthouse default mobile emulation; local Chrome; shared Mac host and variable load',lighthouse_version=j.get('lighthouseVersion'),html_bytes=weight(['Document']),css_bytes=weight(['Stylesheet']),js_bytes=weight(['Script']),image_bytes=weight(['Image']),font_bytes=weight(['Font']),requests=len(network),lcp_ms=au.get('largest-contentful-paint',{}).get('numericValue',na),inp_ms=na,cls=au.get('cumulative-layout-shift',{}).get('numericValue',na),ttfb_ms=au.get('server-response-time',{}).get('numericValue',na),source=str(f.relative_to(p)),notes='Lab only. No causal or field-CWV claim. '+str(j.get('runtimeError') or 'Successful run.')))
